/* =========================================================
   DURDENVPN FOOTER
   ========================================================= */

.durden-footer {
    position: relative;
    width: 100%;
    overflow: hidden;

    background:
        radial-gradient(
            circle at 85% 20%,
            rgba(180, 0, 0, 0.08),
            transparent 32%
        ),
        #080808;

    border-top: 1px solid rgba(255, 255, 255, 0.08);

    color: #ffffff;

    font-family:
        Inter,
        Arial,
        Helvetica,
        sans-serif;

    margin-top: 80px;
}


/* subtle red glow */

.durden-footer__glow {
    position: absolute;

    width: 500px;
    height: 500px;

    right: -250px;
    top: -250px;

    background: rgba(180, 0, 0, 0.08);

    filter: blur(100px);

    pointer-events: none;
}


/* main container */

.durden-footer__inner {
    position: relative;

    max-width: 1280px;

    margin: 0 auto;

    padding:
        70px 32px 30px;
}


/* =========================================================
   TOP SECTION
   ========================================================= */

.durden-footer__top {
    display: flex;

    justify-content: space-between;

    gap: 80px;

    padding-bottom: 55px;
}


/* =========================================================
   BRAND
   ========================================================= */

.durden-footer__brand {
    max-width: 430px;
}


.durden-footer__logo {
    font-size: 30px;

    font-weight: 900;

    letter-spacing: -1.5px;

    line-height: 1;

    color: #ffffff;
}


.durden-footer__logo span {
    color: #d40000;
}


.durden-footer__tagline {
    margin-top: 14px;

    margin-bottom: 18px;

    color: #d40000;

    font-size: 12px;

    font-weight: 800;

    letter-spacing: 2px;

    text-transform: uppercase;
}


.durden-footer__description {
    margin: 0;

    max-width: 410px;

    color: #777777;

    font-size: 14px;

    line-height: 1.7;
}


/* =========================================================
   LINKS
   ========================================================= */

.durden-footer__links {
    display: flex;

    gap: 75px;
}


.durden-footer__column {
    display: flex;

    flex-direction: column;

    gap: 12px;

    min-width: 150px;
}


.durden-footer__title {
    margin-bottom: 8px;

    color: #ffffff;

    font-size: 11px;

    font-weight: 800;

    letter-spacing: 2px;

    text-transform: uppercase;
}


.durden-footer__column a {
    position: relative;

    width: fit-content;

    color: #686868;

    text-decoration: none;

    font-size: 13px;

    transition:
        color 0.2s ease,
        transform 0.2s ease;
}


.durden-footer__column a::before {
    content: "";

    position: absolute;

    left: 0;
    bottom: -3px;

    width: 0;
    height: 1px;

    background: #d40000;

    transition: width 0.2s ease;
}


.durden-footer__column a:hover {
    color: #ffffff;

    transform: translateX(3px);
}


.durden-footer__column a:hover::before {
    width: 100%;
}


/* =========================================================
   WARNING
   ========================================================= */

.durden-footer__warning {
    display: flex;

    align-items: flex-start;

    gap: 16px;

    padding: 18px 20px;

    border: 1px solid rgba(212, 0, 0, 0.2);

    background:
        linear-gradient(
            90deg,
            rgba(212, 0, 0, 0.07),
            rgba(212, 0, 0, 0.015)
        );
}


.durden-footer__warning-icon {
    display: flex;

    flex-shrink: 0;

    align-items: center;
    justify-content: center;

    width: 28px;
    height: 28px;

    border: 1px solid #d40000;

    color: #d40000;

    font-size: 14px;

    font-weight: 900;
}


.durden-footer__warning-title {
    margin-bottom: 5px;

    color: #ffffff;

    font-size: 11px;

    font-weight: 900;

    letter-spacing: 2px;
}


.durden-footer__warning-text {
    color: #666666;

    font-size: 12px;

    line-height: 1.6;
}


/* =========================================================
   DIVIDER
   ========================================================= */

.durden-footer__divider {
    width: 100%;

    height: 1px;

    margin-top: 35px;

    background:
        linear-gradient(
            90deg,
            transparent,
            rgba(255, 255, 255, 0.12),
            transparent
        );
}


/* =========================================================
   BOTTOM
   ========================================================= */

.durden-footer__bottom {
    display: flex;

    align-items: center;

    justify-content: space-between;

    gap: 20px;

    padding-top: 25px;
}


.durden-footer__copy {
    color: #444444;

    font-size: 10px;

    font-weight: 700;

    letter-spacing: 1.5px;
}


/* system status */

.durden-footer__status {
    display: flex;

    align-items: center;

    gap: 8px;

    color: #555555;

    font-size: 10px;

    font-weight: 700;

    letter-spacing: 1.3px;
}


.durden-footer__status-dot {
    width: 6px;
    height: 6px;

    border-radius: 50%;

    background: #45c96b;

    box-shadow:
        0 0 8px rgba(69, 201, 107, 0.7);
}


/* =========================================================
   MOBILE
   ========================================================= */

@media (max-width: 900px) {

    .durden-footer__top {
        flex-direction: column;

        gap: 45px;
    }


    .durden-footer__links {
        display: grid;

        grid-template-columns:
            repeat(3, 1fr);

        gap: 30px;
    }

}


@media (max-width: 600px) {

    .durden-footer {
        margin-top: 50px;
    }


    .durden-footer__inner {
        padding:
            50px 20px 25px;
    }


    .durden-footer__links {
        grid-template-columns: 1fr 1fr;

        gap: 35px 20px;
    }


    .durden-footer__warning {
        padding: 15px;
    }


    .durden-footer__bottom {
        flex-direction: column;

        align-items: flex-start;
    }


    .durden-footer__status {
        margin-top: 3px;
    }

}


@media (max-width: 400px) {

    .durden-footer__links {
        grid-template-columns: 1fr;
    }

}
